//! The Xila version this ABI belongs to, generated by the build script from
//! [`xila_version::RUNNING`]. Native images record it in their ABI note, and
//! the host's `XilaApi.version` carries it packed as `(major << 16) | minor`.

include!(concat!(env!("OUT_DIR"), "/version.rs"));

const _: () = assert!(
    XILA_VERSION_MAJOR == xila_version::RUNNING.major as u32
        && XILA_VERSION_MINOR == xila_version::RUNNING.minor as u32
);
